fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();
    
    // Create X matrix: each row is a copy of x
    let mut x_grid = Vec::with_capacity(rows);
    for _ in 0..rows {
        x_grid.push(x.clone());
    }
    
    // Create Y matrix: each row has the same y value in all columns
    let mut y_grid = Vec::with_capacity(rows);
    for i in 0..rows {
        let row = vec![y[i]; cols];
        y_grid.push(row);
    }
    
    (x_grid, y_grid)
}